% Left axis: pressures
ax = gca; %[output:21343caf]
yyaxis(ax, 'left'); %[output:21343caf]
hP1 = plot(ax, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on'); %[output:21343caf]
hP2 = plot(ax, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5); %[output:21343caf]
ylabel(ax, "Overpressure [kPa]", 'Interpreter', 'latex'); %[output:21343caf]
ax.YColor = 'k'; %[output:21343caf]

% Right axis: triggers
yyaxis(ax, 'right'); %[output:21343caf]
hTr1 = plot(ax, t1, y1_tr, 'Color', Red_Dark, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on'); %[output:21343caf]
hTr2 = plot(ax, t2, y2_tr, 'Color', Red_Light, 'LineStyle', ':', 'LineWidth', 0.5); %[output:21343caf]
ylabel(ax, 'Trigger Voltage [V]', 'Interpreter', 'latex'); %[output:21343caf]
ax.YColor = Red_Dark; %[output:21343caf]

% Common formatting
xlabel('Time [s]', 'Interpreter', 'latex'); %[output:21343caf]
title({"{\textbf{Run Wk22-02-02 (Conc. Target $H_2$ 18 vol.$\%$)}}",'LU vs Kistler DAQs','(Flush Mounted Pressure Sensors)'}, 'Interpreter', 'latex'); %[output:21343caf]

legend([hP1,hP2,hTr1,hTr2], ... %[output:21343caf]
    {'Pressure (DAQ-1) '+ ch1_p,'Pressure (DAQ-4) ' + ch2_p,'Trigger (DAQ-1) ' + ch1_tr,'Trigger (DAQ-4) ' + ch2_tr}, ... %[output:21343caf]
    'Location','northeast', 'Interpreter','latex'); %[output:21343caf]

grid on; %[output:21343caf]

% --- Dynamic axis limits (5% padding) ---
padFrac = 0.05;

% X limits combining t1 and t2
tAll = [t1(:); t2(:)];
tMin = min(tAll); tMax = max(tAll);
tRange = tMax - tMin;
if tRange == 0
    tPad = abs(tMin)*padFrac + 1e-3;
else
    tPad = padFrac * tRange;
end
xlim(ax, [tMin - tPad, tMax + tPad]); %[output:21343caf]

% Left axis (pressures)
pAll = [y1_p(:); y2_p(:)];
pMin = min(pAll); pMax = max(pAll);
pRange = pMax - pMin;
if pRange == 0
    pPad = abs(pMin)*padFrac + 1e-3;
else
    pPad = padFrac * pRange;
end
yyaxis(ax, 'left'); %[output:21343caf]
ylim(ax, [pMin - pPad, pMax + pPad]); %[output:21343caf]

% Right axis (triggers)
