%[text] **Run Wk22\_02\_03**
t1 = run_Wk22_02_03.DAQ_1.t_s;
y1_p = run_Wk22_02_03.DAQ_1.signal(:,1);
y1_tr = run_Wk22_02_03.DAQ_1.signal(:,2);

t2 = run_Wk22_02_03.DAQ_4.t_s;
