figure('Units','centimeters','Position',[10 10 18 12]); %[output:9b3ba716]

% Left axis: pressures
ax = gca; %[output:9b3ba716]
yyaxis(ax, 'left'); %[output:9b3ba716]
hP1 = plot(ax, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5); hold(ax,'on'); %[output:9b3ba716]
hP2 = plot(ax, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5); %[output:9b3ba716]
ylabel(ax, "Overpressure [kPa]", 'Interpreter', 'latex'); %[output:9b3ba716]
